def main():
    with open('/home/user/TheosophicalAlchemyDB/data/prototype_data.json') as f:
        data = json.load(f)

    texts = data.get('texts', [])
    results = []

    for t in texts:
        tid = t.get('id')
        if tid not in ESSAYS:
            continue
        old_essay_len = len(t.get('essay', ''))
        old_summary_len = len(t.get('summary', ''))
        updates = ESSAYS[tid]
        t['essay'] = updates['essay']
        t['summary'] = updates['summary']
        new_essay_len = len(t['essay'])
        new_summary_len = len(t['summary'])
        results.append(f"id={tid} ({t.get('title','')}): essay {old_essay_len} -> {new_essay_len}, summary {old_summary_len} -> {new_summary_len}")

    with open('/home/user/TheosophicalAlchemyDB/data/prototype_data.json', 'w', encoding='utf-8') as f:
        json.dump(data, f, ensure_ascii=False, indent=2)

    print("Updated IDs 1-20:")
    for r in results:
        print(" ", r)
    print(f"\nTotal updated: {len(results)}")

if __name__ == '__main__':
    main()
